mapper.select:
SELECT c.* FROM coupon c JOIN user_coupon uc ON c.id = uc.coupon_id
WHERE
AND uc.is_deleted = 0 AND uc.status = 0 AND uc.user_id = #{userId}

mapper.update:
UPDATE coupon
SET sending_stock = sending_stock + 1,
    version = version + 1,
    update_time = NOW()
WHERE id = #{couponId}
  AND version = #{oldVersion}
  AND sending_stock = #{oldSendingStock}
  AND is_deleted = 0
  AND status = 1
